// ============================================
// n8n CODE NODE
// Parse AI Agent Email JSON Output
// Handles:
// 1. Valid JSON array
// 2. Markdown wrapped JSON
// 3. "NO EMPLOYEE SHCEDULING ALLOCATION"
// ============================================

// ============================================
// INPUT
// ============================================

const rawOutput =
  $input.first()?.json?.output || '';

// ============================================
// HELPERS
// ============================================

function safeString(value) {

  if (
    value === null ||
    value === undefined
  ) {
    return '';
  }

  return String(value).trim();
}

function cleanJsonString(str) {

  return str
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
}

// ============================================
// CLEAN INPUT
// ============================================

const cleanedOutput =
  cleanJsonString(
    safeString(rawOutput)
  );

// ============================================
// HANDLE:
// NO EMPLOYEE SHCEDULING ALLOCATION
// ============================================

if (
  cleanedOutput ===
  'NO EMPLOYEE SHCEDULING ALLOCATION'
) {

  return [
    {
      json: {

        success: true,

        no_employee_allocation: true,

        message:
          'NO EMPLOYEE SCHEDULING ALLOCATION'
      }
    }
  ];
}

// ============================================
// PARSE JSON
// ============================================

let parsed = [];

try {

  parsed =
    JSON.parse(cleanedOutput);

} catch (error) {

  return [
    {
      json: {

        success: false,

        message:
          'Failed to parse AI output',

        error:
          error.message,

        raw_output:
          rawOutput
      }
    }
  ];
}

// ============================================
// VALIDATE ARRAY
// ============================================

if (!Array.isArray(parsed)) {

  return [
    {
      json: {

        success: false,

        message:
          'Parsed output is not an array',

        parsed_output:
          parsed
      }
    }
  ];
}

// ============================================
// OUTPUT
// ============================================

return parsed.map(item => ({

  json: {

    success: true,

    no_employee_allocation: false,

    employee_name:
      item.employee_name || '',

    employee_email:
      item.employee_email || '',

    subject:
      item.subject || '',

    body:
      item.body || ''

  }

}));

const employees =
  $('When Executed by Another Workflow').first().json.Employees_New_Project_Hours || [];

const output = [];

// Handle no employee allocation case
if (
  employees.length &&
  employees[0].MESSAGE === 'NO EMPLOYEE NEW PROJECT HOURS'
) {
  return [{
    json: {
      emails: ["No employee allocated to this project"]
    }
  }];
}

// Normal processing
for (const item of employees) {

  const names = (item.employee || '')
    .split(/\s+and\s+/i)
    .map(name => name.trim())
    .filter(Boolean);

  for (const name of names) {

    output.push({
      json: {
        employee: name,
        task_type_code: item.task_type
      }
    });

  }
}

return output;

const names = [];
const emails = [];

for (const item of $input.all()) {

  const employee = item.json.data?.[0];

  if (!employee) continue;

  names.push(employee.name);
  emails.push(employee.email);
}

return [
  {
    json: {
      names,
      emails
    }
  }
];

const employees =
$('When Executed by Another Workflow').first().json.Employees_New_Project_Hours || [];

const output = [];

for (const item of employees) {

  const names = item.employee
    .split(/\s+and\s+/i)
    .map(name => name.trim());

  for (const name of names) {

    output.push({
      json: {
        employee: name,
        task_type_code: item.task_type
      }
    });

  }
}

return output;
